// probe/hardening1713.test.ts
init_policyGateway();
init_toolSchema();
init_agui();
import { describe as describe3, it } from "node:test";
import assert2 from "node:assert";
describe3("hardening1713 \u2014 PolicyGateway, tool schemas, AG-UI emitter", () => {
  it("policyGateway: risky tools STEER with a named rule; safe tools ALLOW under the sovereign safe-class rule", () => {
    _resetPolicyRulesForProbe();
    const r1 = propose({ tool: "workspace_write", detail: "write file.txt", args: { name: "file.txt", content: "hi" } });
    assert2.strictEqual(r1.decision, "steer", "workspace_write must steer to approval");
    assert2.strictEqual(r1.rule, "risky-tool-requires-approval");
    assert2.ok(r1.audit.kind === "policy" && r1.audit.tool === "workspace_write");
    const r2 = propose({ tool: "dispatch_mission", detail: "dispatch a mission" });
    assert2.strictEqual(r2.decision, "steer", "dispatch_mission must steer to approval");
    const r3 = propose({ tool: "shell_exec", detail: "ls", args: { command: "ls" } });
    assert2.strictEqual(r3.decision, "steer", "shell_exec must steer to approval (added to riskyTools in 17.1.3)");
    assert2.ok(riskyTools.has("shell_exec"), "shell_exec is in the risky set");
    const r4 = propose({ tool: "system_info", detail: "system info" });
    assert2.strictEqual(r4.decision, "allow", "system_info is not risky");
    assert2.strictEqual(r4.rule, "sovereign-safe-class");
  });
  it("policyGateway: custom rules can deny and are evaluated in registration order", () => {
    _resetPolicyRulesForProbe();
    registerPolicyRule((input2) => {
      if (input2.tool === "web_search" && String(input2.args?.query ?? "").toLowerCase().includes("password")) {
        return { decision: "deny", rule: "no-password-queries", reason: "web_search refuses queries that look like credential exfiltration" };
      }
      return null;
    });
    const denied = propose({ tool: "web_search", args: { query: "my password is hunter2" }, detail: "" });
    assert2.strictEqual(denied.decision, "deny");
    assert2.strictEqual(denied.rule, "no-password-queries");
    const allowed = propose({ tool: "web_search", args: { query: "SelfImpulse 17.1" }, detail: "" });
    assert2.strictEqual(allowed.decision, "allow");
    _resetPolicyRulesForProbe();
  });
  it("tool schemas: Zod schemas accept valid args and reject invalid args with messages", () => {
    const good = WorkspaceWriteSchema.safeParse({ name: "notes.txt", content: "hello" });
    assert2.ok(good.success, "valid workspace_write args accepted");
    const bad = WorkspaceWriteSchema.safeParse({ name: "../etc/passwd", content: "x" });
    assert2.ok(!bad.success, "path-traversal filename rejected");
    const tooBig = WorkspaceWriteSchema.safeParse({ name: "x.txt", content: "x".repeat(2e6) });
    assert2.ok(!tooBig.success, "file over 1 MB rejected");
    const empty2 = ShellExecSchema.safeParse({ command: "" });
    assert2.ok(!empty2.success, "empty shell command rejected");
    const dispatch = DispatchMissionSchema.safeParse({ objective: "" });
    assert2.ok(!dispatch.success, "empty objective rejected");
  });
  it("tool schemas: validateArgs + formatParseErrors produce a single-line retry message", () => {
    const res = validateArgs("workspace_write", { name: "", content: "hi" });
    assert2.ok(!res.success, "empty name rejected via validateArgs");
    const msg = formatParseErrors(res);
    assert2.ok(msg.length > 0 && msg.includes("name"), "errors mention the failing field");
    const ok = validateArgs("system_info", {});
    assert2.ok(ok.success, "system_info accepts empty args");
  });
  it("tool schemas: withSchema wraps a function, performs ONE retry via repair callback", async () => {
    const shout = async (args) => args.text.toUpperCase();
    const { z: z2 } = await Promise.resolve().then(() => (init_zod(), zod_exports));
    const ShoutSchema = z2.object({ text: z2.string().min(1) });
    const plain = withSchema(ShoutSchema, shout);
    const bad = await plain({ text: "" });
    assert2.strictEqual(bad.ok, false);
    assert2.strictEqual(bad.retried, false);
    assert2.ok(bad.errors.length >= 1);
    assert2.ok(bad.errors[0].toLowerCase().includes("text"), "error names the failing field");
    let repairCalls = 0;
    const withFix = withSchema(ShoutSchema, shout, {
      repair: (_raw, errs) => {
        repairCalls++;
        return { text: "fixed-" + errs };
      }
    });
    const fixed = await withFix({ text: "" });
    assert2.strictEqual(fixed.ok, true, "repaired input runs");
    assert2.ok(String(fixed.value).startsWith("FIXED-"), "repaired value runs through fn");
    assert2.strictEqual(repairCalls, 1, "repair called exactly once");
    const withNoFix = withSchema(ShoutSchema, shout, { repair: () => null });
    const refused = await withNoFix({ text: "" });
    assert2.strictEqual(refused.ok, false);
    assert2.strictEqual(refused.retried, true, "retried flag set when repair was attempted");
  });
  it("AG-UI emitter: fires and receives a typed event sequence", () => {
    const runId = nextRunId();
    const threadId = "th_probe";
    const seen = [];
    const off1 = agui.on("RUN_STARTED", () => seen.push("start"));
    const off2 = agui.on("TEXT_MESSAGE_CONTENT", (e) => seen.push(`text:${e.delta}`));
    const off3 = agui.on("TOOL_CALL_START", (e) => seen.push(`tool:${e.tool}`));
    const off4 = agui.on("INTERRUPT", () => seen.push("interrupt"));
    const off5 = agui.on("RUN_FINISHED", (e) => seen.push(`finish:${e.outcome}`));
    emitRunStarted(runId, threadId);
    emitTextStart(runId, threadId, "m1");
    emitTextChunk(runId, threadId, "m1", "hello ");
    emitTextChunk(runId, threadId, "m1", "world");
    emitTextEnd(runId, threadId, "m1");
    emitToolStart(runId, threadId, "t1", "workspace_write");
    emitToolResult(runId, threadId, "t1", "wrote notes.txt", true);
    emitInterrupt(runId, threadId, "a1", "dispatch_mission", "needs approval");
    emitRunFinished(runId, threadId, "completed");
    off1();
    off2();
    off3();
    off4();
    off5();
    assert2.deepStrictEqual(seen, [
      "start",
      "text:hello ",
      "text:world",
      "tool:workspace_write",
      "interrupt",
      "finish:completed"
    ]);
  });
  it("integration: runSelfImpulseToolCall routes through PolicyGateway (custom DENY blocks execution)", async () => {
    _resetPolicyRulesForProbe();
    registerPolicyRule((input2) => {
      if (input2.tool === "system_info") {
        return { decision: "deny", rule: "probe-block", reason: "probe deny" };
      }
      return null;
    });
    const events = [];
    const off1 = agui.on("INTERRUPT", (e) => events.push(`interrupt:${e.tool}:${e.reason}`));
    const off2 = agui.on("TOOL_CALL_RESULT", (e) => events.push(`result:${e.ok}`));
    const { runSelfImpulseToolCall: runSelfImpulseToolCall2, resetSelfImpulseForProbe } = await Promise.resolve().then(() => (init_selfimpulse(), selfimpulse_exports));
    resetSelfImpulseForProbe?.();
    const r = await runSelfImpulseToolCall2("system_info", {}, { blockOnGate: false });
    off1();
    off2();
    assert2.strictEqual(r.ok, false, "policy DENY should fail the call");
    assert2.ok(/policy denied/i.test(r.output), "output says policy denied");
    assert2.ok(events.some((e) => e.startsWith("interrupt:system_info")), "INTERRUPT emitted");
    _resetPolicyRulesForProbe();
  });
  it("integration: runSelfImpulseToolCall rejects bad args via Zod validateArgs before tool.run", async () => {
    _resetPolicyRulesForProbe();
    const { runSelfImpulseToolCall: runSelfImpulseToolCall2, resetSelfImpulseForProbe } = await Promise.resolve().then(() => (init_selfimpulse(), selfimpulse_exports));
    resetSelfImpulseForProbe?.();
    const bad = await runSelfImpulseToolCall2("web_search", { query: "" }, { blockOnGate: false });
    assert2.strictEqual(bad.ok, false, "empty query rejected");
    assert2.ok(/schema validation failed/i.test(bad.output), "mentions schema validation");
  });
  it("integration: runSelfImpulseToolCall emits AG-UI RUN_STARTED/TOOL_*/RUN_FINISHED on a safe call", async () => {
    _resetPolicyRulesForProbe();
    const events = [];
    const off1 = agui.on("RUN_STARTED", () => events.push("RUN_STARTED"));
    const off2 = agui.on("TOOL_CALL_START", () => events.push("TOOL_CALL_START"));
    const off3 = agui.on("TOOL_CALL_ARGS", () => events.push("TOOL_CALL_ARGS"));
    const off4 = agui.on("TOOL_CALL_RESULT", () => events.push("TOOL_CALL_RESULT"));
    const off5 = agui.on("RUN_FINISHED", (e) => events.push(`RUN_FINISHED:${e.outcome}`));
    const { runSelfImpulseToolCall: runSelfImpulseToolCall2, resetSelfImpulseForProbe } = await Promise.resolve().then(() => (init_selfimpulse(), selfimpulse_exports));
    resetSelfImpulseForProbe?.();
    const r = await runSelfImpulseToolCall2("system_info", {}, { blockOnGate: false });
    off1();
    off2();
    off3();
    off4();
    off5();
    assert2.strictEqual(r.ok, true, "system_info succeeds");
    assert2.ok(events.includes("RUN_STARTED"), "RUN_STARTED fired");
    assert2.ok(events.includes("TOOL_CALL_START"), "TOOL_CALL_START fired");
    assert2.ok(events.includes("TOOL_CALL_RESULT"), "TOOL_CALL_RESULT fired");
    const finish = events.find((e) => e.startsWith("RUN_FINISHED:"));
    assert2.strictEqual(finish, "RUN_FINISHED:completed", "run completed");
    _resetPolicyRulesForProbe();
  });
  it("integration: RISKY_TOOLS exported from selfimpulse.ts matches policyGateway.riskyTools (single source of truth)", async () => {
    const { RISKY_TOOLS: RISKY_TOOLS2 } = await Promise.resolve().then(() => (init_selfimpulse(), selfimpulse_exports));
    assert2.ok(RISKY_TOOLS2.has("shell_exec"), "RISKY_TOOLS includes shell_exec (17.1.3 fix)");
    assert2.ok(RISKY_TOOLS2.has("workspace_write"));
    assert2.ok(RISKY_TOOLS2.has("dispatch_mission"));
    assert2.strictEqual(RISKY_TOOLS2.size, riskyTools.size, "sets are the same size");
  });
  it("integration: runSelfImpulseToolCall performs ONE structured retry on fixable schema errors", async () => {
    _resetPolicyRulesForProbe();
    const { runSelfImpulseToolCall: runSelfImpulseToolCall2, registerProbeTool: registerProbeTool2, deregisterProbeTool: deregisterProbeTool2 } = await Promise.resolve().then(() => (init_selfimpulse(), selfimpulse_exports));
    let calls = 0;
    let lastArgs = null;
    registerProbeTool2("web_search", {
      name: "web_search",
      risky: false,
      description: "probe stub",
      run: async (args) => {
        calls++;
        lastArgs = args;
        return `searched: ${String(args.query)}`;
      }
    });
    try {
      const refused = await runSelfImpulseToolCall2("web_search", {}, { blockOnGate: false });
      assert2.strictEqual(refused.ok, false, "missing query refused after one retry");
      assert2.ok(/one retry/i.test(refused.output), "refusal message mentions one retry");
      assert2.strictEqual(calls, 0, "tool never ran on unfixable input");
      calls = 0;
      lastArgs = null;
      const fixed = await runSelfImpulseToolCall2("web_search", { query: "  what is SelfImpulse  " }, { blockOnGate: false });
      assert2.strictEqual(fixed.ok, true, `trimmed query succeeds on retry; got ${fixed.output}`);
      assert2.strictEqual(calls, 1, "tool ran exactly once after repair");
      assert2.strictEqual(lastArgs?.query, "what is SelfImpulse", "args were repaired in-place before run()");
      calls = 0;
      lastArgs = null;
      const fresh = await runSelfImpulseToolCall2("web_search", { query: "hello" }, { blockOnGate: false });
      assert2.strictEqual(fresh.ok, true);
      assert2.strictEqual(calls, 1, "valid args run once without retry");
    } finally {
      deregisterProbeTool2("web_search");
    }
    _resetPolicyRulesForProbe();
  });
  it("integration: dispatch_mission is schema-validated through the same retry throat (empty objective refused)", async () => {
    _resetPolicyRulesForProbe();
    const { runSelfImpulseToolCall: runSelfImpulseToolCall2 } = await Promise.resolve().then(() => (init_selfimpulse(), selfimpulse_exports));
    const refused = await runSelfImpulseToolCall2("dispatch_mission", { objective: "" }, { blockOnGate: false });
    assert2.strictEqual(refused.ok, false, "empty objective refused");
    assert2.ok(/schema validation failed/i.test(refused.output), "output names schema failure");
    const ws = await runSelfImpulseToolCall2("dispatch_mission", { objective: "   " }, { blockOnGate: false });
    assert2.strictEqual(ws.ok, false, "whitespace-only objective refused after trim");
    _resetPolicyRulesForProbe();
  });
  it("integration: retry receipt event carries rawArgs + repairedArgs + repairSource for audit", async () => {
    _resetPolicyRulesForProbe();
    const { runSelfImpulseToolCall: runSelfImpulseToolCall2, selfimpulseSession: selfimpulseSession2 } = await Promise.resolve().then(() => (init_selfimpulse(), selfimpulse_exports));
    let calls = 0;
    let lastArgs = null;
    const { registerProbeTool: registerProbeTool2, deregisterProbeTool: deregisterProbeTool2 } = await Promise.resolve().then(() => (init_selfimpulse(), selfimpulse_exports));
    registerProbeTool2("web_search", {
      name: "web_search",
      risky: false,
      description: "probe",
      run: async (args) => {
        calls++;
        lastArgs = args;
        return `ok:${args.query}`;
      }
    });
    try {
      const r = await runSelfImpulseToolCall2("web_search", { query: "  audit me  " }, { blockOnGate: false });
      assert2.strictEqual(r.ok, true);
      assert2.strictEqual(calls, 1);
      assert2.strictEqual(lastArgs?.query, "audit me", "tool got repaired args");
      const sess = selfimpulseSession2();
      const last = sess.receipts[sess.receipts.length - 1];
      const retryEvt = last.receipt.events.find((e) => e.kind === "tool.schema_retry");
      const r2 = await runSelfImpulseToolCall2("web_search", {}, { blockOnGate: false });
      assert2.strictEqual(r2.ok, false);
      const sess2 = selfimpulseSession2();
      const refEvt = sess2.receipts[sess2.receipts.length - 1].receipt.events.find(
        (e) => e.kind === "tool.schema_refused"
      );
      assert2.ok(refEvt, "schema_refused event present");
      assert2.ok(refEvt && typeof refEvt.data.rawArgs === "object", "rawArgs auditable");
      assert2.ok(refEvt && "repairSource" in refEvt.data, "repairSource present");
      assert2.ok(refEvt && "repairReason" in refEvt.data, "repairReason present");
      assert2.strictEqual(calls, 1, "refused path never ran the tool");
    } finally {
      deregisterProbeTool2("web_search");
    }
    _resetPolicyRulesForProbe();
  });
});
